let s=fresh(),room='power',role=0;const names={energy:'Energía',life:'Soporte vital',safety:'Seguridad',food:'Alimentos',science:'Ciencia'},colors=['#f5cb75','#89dbef','#b8a6ef','#a6efce','#f6a7ae'],roles=['Sol · Ingeniería','Kai · Soporte vital','Noa · Botánica','Luz · Ciencia'];const $=id=>document.getElementById(id);function modal(html){$('modal').innerHTML=html;$('dialog').showModal()}
function render(){$('day').textContent=`DÍA ${s.day} / 7`;$('resources').innerHTML=Object.entries(names).map(([k,n],i)=>`<div class="resource" style="--c:${colors[i]}"><label>${n}</label><b>${s[k]}<small> /100</small></b><div class="bar"><i style="width:${s[k]}%"></i></div></div>`).join('');$('crew').innerHTML=roles.map((r,i)=>`<button class="${role===i?'selected':''}" onclick="selectRole(${i})">${['🟡','🔵','🟢','🟣'][i]} ${r}</button>`).join('');const event=s.day===5?['ALERTA · REGISTRO HISTÓRICO NASA','Actividad solar','Una fulguración histórica contextualiza este ejercicio. Prepara el refugio hoy para reducir la pérdida de seguridad.']:s.day===3?['EVENTO SIMULADO','Menos energía disponible','La generación será menor este turno. Alinear paneles te ayudará a conservar reservas.']:s.day===6?['EVENTO SIMULADO','Fuga en soporte vital','El sistema perderá 26 unidades al finalizar el día. Prioriza su mantenimiento.']:['OPERACIÓN NOMINAL','La base depende de ti','Tienes tres tareas por día. Mantén todas las reservas por encima de cero y alcanza 60 de ciencia al terminar el día 7.'];$('eventlabel').textContent=event[0];$('eventtitle').textContent=event[1];$('eventtext').textContent=event[2];const a=actions[room];$('tasktitle').textContent=a.name;$('tasktext').textContent=a.text;$('cost').textContent=Object.entries(a.cost).map(([k,v])=>`−${v} ${names[k]}`).concat(Object.entries(a.gain).map(([k,v])=>`+${v} ${names[k]} (máx. 100)`)).join(' · ');$('action').textContent=s.used.includes(room)?'Tarea completada hoy':'Completar tarea →';$('action').disabled=s.over||!s.tasks||s.used.includes(room)||Object.entries(a.cost).some(([k,v])=>s[k]<v);$('remaining').textContent=`${s.tasks} de 3 tareas disponibles · una por sala al día`;$('end').disabled=s.over;$('log').innerHTML=s.log.map(x=>`<p>${x}</p>`).join('')||'<p>Bienvenido a Aurora. Visita las salas, revisa los costos y realiza hasta tres tareas antes de finalizar cada día.</p>'}
function selectRole(i){role=i;$('astronaut').style.background=colors[i];render()}function visit(r){room=r;const pos={power:[18,32],life:[49,32],food:[80,32],shield:[28,80],science:[72,80]}[r];$('astronaut').style.left=pos[0]+'%';$('astronaut').style.top=pos[1]+'%';render()}function act(){if(apply(s,room)){s.log[0]=roles[role]+' · '+s.log[0];render()}}function endDay(){advance(s);render();if(s.over)result()}function result(){const failed=Object.keys(names).filter(k=>k!=='science'&&s[k]===0);modal(`<small>INFORME DE MISIÓN</small><h1>${failed.length?'Misión interrumpida':s.science>=60?'¡Misión cumplida!':'Base a salvo. Ciencia pendiente.'}</h1><p>${failed.length?'Se agotó: '+failed.map(k=>names[k]).join(', ')+'. Dedica más tareas a estos sistemas antes de avanzar.':s.science>=60?'Tu equipo equilibró supervivencia e investigación durante siete días.':'Sobreviviste siete días, pero faltó alcanzar 60 de ciencia. Reserva tres tareas de investigación en tu siguiente intento.'}</p><p>Ciencia: ${s.science}/100 · Objetivo: 60. ${s.log.filter(x=>x.includes('Analizar muestras')).length} tareas de investigación.</p><h2>Tu última decisión y su consecuencia</h2><p>${s.log.slice(0,2).join('<br><br>')}</p><button class="primary" onclick="resetGame();document.querySelector('dialog').close()">Intentar otra estrategia</button>`)}function resetGame(){s=fresh();visit('power');render()}function meeting(){modal('<small>REUNIÓN DE EQUIPO</small><h2>Una base. Cuatro perspectivas.</h2><p>Jueguen por turnos en este dispositivo. Cada persona puede representar un rol. No hay conexión multijugador en este prototipo.</p><ul>'+Object.entries(names).map(([k,n])=>`<li>${n}: ${s[k]}/100</li>`).join('')+'</ul><p>¿Qué reserva está en peligro? ¿Qué tarea pueden posponer? Acuerden las tres prioridades antes de seguir. La reunión no consume un turno.</p>')}
function eventScience(){modal(`<small>CIENCIA / SIMULACIÓN</small><h2>${s.day===5?'Un registro real, un escenario educativo':'Sistemas conectados'}</h2><p>NASA ECLSS describe sistemas para recuperar agua, generar oxígeno y mantener el aire habitable. El juego simplifica estas funciones en soporte vital y consumo de energía.</p><p><a href="https://www.nasa.gov/reference/environmental-control-and-life-support-systems-eclss/" target="_blank" rel="noopener">Consultar NASA ECLSS ↗</a></p><h2>NASA CCMC · DONKI</h2><p>Registro histórico: ${historical.flrID}<br>Inicio UTC: ${historical.beginTime}<br>Pico UTC: ${historical.peakTime}<br>Clase: ${historical.classType}<br>Instrumento: ${historical.instruments[0].displayName}</p><p><a href="${historical.link}" target="_blank" rel="noopener">Ver registro original ↗</a> · <a href="donki.json">JSON histórico local</a></p><p>Este registro activa narrativamente la alerta del día 5. No mide la dosis de una base lunar. Las pérdidas de seguridad, el tiempo, las cosechas y todos los valores del juego son supuestos educativos, no predicciones NASA.</p>`)}function showSources(){modal('<small>BIBLIOTECA CIENTÍFICA</small><h2>Del documento al juego</h2><p>Se extrajeron las 15 páginas y los 11 enlaces únicos. ECLSS fundamenta las relaciones del soporte vital; un registro DONKI descargado alimenta la alerta. Las demás fuentes se conservan como referencias, no como datasets integrados.</p><p><a href="guia-extraida.txt">Leer extracción completa del PDF ↗</a> · <a href="donki.json">Datos DONKI originales ↗</a></p><ol>'+sources.map(u=>`<li><a href="${u}" target="_blank" rel="noopener">${u}</a></li>`).join('')+'</ol><p>La guía es independiente y corresponde a Junior Astronaut Mission Trainer. RadLab, OSDR, Mars Trek y CSA son ampliaciones. No se usan imágenes, personajes ni sonidos de Among Us.</p>')}
render();modal('<small>BIENVENIDO A BASE AURORA</small><h1>Tu tripulación<br>cuenta contigo.</h1><p>Sobrevive siete días y consigue al menos 60 de ciencia.</p><ol><li>Selecciona una sala del mapa para viajar.</li><li>Revisa sus costos y completa una tarea.</li><li>Solo tienes tres tareas por día: coordina tus prioridades.</li><li>Finaliza el día para ver consumos y consecuencias.</li></ol><p>Las barras representan unidades educativas. Puedes jugar solo o repartir los cuatro roles en un mismo dispositivo.</p><button class="primary" onclick="document.querySelector(\'dialog\').close()">Iniciar misión →</button>');
